def poblar(apps, schema_editor):
    """Lleva lo que ya existe a los tres niveles: siglas, orden contiguo, códigos OO-PPP.TT.SSS y la tarea (nivel 2) de cada subtarea."""
    from nucleo import siglas
    Proceso, TareaPrincipal, Tarea = (apps.get_model("nucleo", n) for n in ("Proceso", "TareaPrincipal", "Tarea"))
    procesos = list(Proceso.objects.order_by("orden", "nombre"))
    ocupadas = set()
    for p in procesos:
        sigla = siglas.SIGLAS_HACIENDA.get(p.nombre)
        p.sigla = sigla if sigla and sigla not in ocupadas else siglas.derivar(p.nombre, ocupadas)
        ocupadas.add(p.sigla)
    for i, p in enumerate(procesos, start=1):  # orden contiguo 1..n; se libera el rango antes para no chocar con la restricción
        Proceso.objects.filter(pk=p.pk).update(orden=1000 + i)
    for i, p in enumerate(procesos, start=1):
        p.orden = i
        p.codigo = f"{i:02d}-{p.sigla}"
        p.save()
        grupos = {}
        for t in Tarea.objects.filter(proceso=p).order_by("secuencia", "id"):
            tp = grupos.get(t.tarea_principal)
            if tp is None:
                tp = TareaPrincipal.objects.create(proceso=p, nombre=t.tarea_principal, numero=len(grupos) + 1, codigo=f"{p.codigo}.{len(grupos) + 1:02d}")
                grupos[t.tarea_principal] = tp
            t.padre = tp
            t.numero = Tarea.objects.filter(padre=tp).count() + 1
            t.codigo = f"{tp.codigo}.{t.numero:03d}"
            t.save()


